"""Create review-gated behavior datasets for non-Network CloudZero Twins.

These are development drafts, not approved QLoRA data.  The generator deliberately
keeps benchmark material out of the output and writes to a separate directory.
"""
import argparse, hashlib, json, re
from pathlib import Path

OUT = Path(__file__).resolve().parents[1] / '.data' / 'training' / 'domain-datasets'
DOMAINS = {
 'WINDOWS': [('AD authentication','domain controller reachability, DNS, time synchronization, and Kerberos evidence','Windows event logs and domain-controller health'),('GPO processing','effective policy, scope, processing events, and an unaffected host','Group Policy operational logs and gpresult'),('IIS availability','listener state, worker process health, bindings, certificates, and upstream dependency','IIS logs and service state'),('SMB access','identity, share permissions, NTFS permissions, name resolution, and client/server timestamps','SMB audit events and effective access'),('RDP failure','listener state, NLA, certificate, firewall, and account policy evidence','RDP event logs and listener state'),('DHCP scope pressure','scope utilization, relay path, lease timing, and affected-segment comparison','DHCP audit log and scope statistics'),('service crash','service dependencies, crash events, startup configuration, and recent changes','Windows event logs and service configuration'),('certificate failure','certificate chain, expiry, hostname, trust store, and clock state','certificate store and application handshake logs'),('patch regression','installed update timeline, affected component, known-good host, and rollback criteria','update history and service telemetry'),('resource pressure','CPU, memory, disk, process identity, workload change, and time window','performance counters and event logs'),('DFS namespace','referrals, site awareness, target health, permissions, and DNS','DFS diagnostics and client event logs'),('scheduled task','task history, run-as identity, trigger, script path, and exit code','Task Scheduler history and security events'),('cluster failover','node health, quorum, storage, role state, and failover events','cluster logs and storage state'),('PowerShell execution','script provenance, policy, identity, endpoint logs, and change approval','PowerShell operational logs'),('time drift','NTP source, offset, domain hierarchy, and authentication timestamps','time service diagnostics')],
 'LINUX': [('systemd startup','unit state, dependency failure, journal timestamps, and recent deployment changes','systemctl status and journal evidence'),('CPU saturation','process ownership, run queue, workload change, and per-process CPU over time','top or pidstat evidence'),('memory pressure','RSS, swap, OOM events, limits, and workload timeline','memory counters and kernel journal'),('disk full','filesystem blocks, inode use, growth source, and service impact','df, du, and filesystem telemetry'),('inode exhaustion','inode consumption, small-file growth, mount scope, and cleanup safety','df -i and file-growth evidence'),('read-only filesystem','kernel errors, device health, mount options, and data-integrity risk','journal and mount/device evidence'),('DNS resolution','resolver configuration, search domains, query results, route, and unaffected host','resolver diagnostics and packet evidence'),('SSH access','listener, route, firewall, account policy, keys, and authentication logs','sshd logs and connection tests'),('permissions','path ownership, mode, ACLs, identity, and recent deployment changes','stat, ACL, and audit evidence'),('package dependency','package transaction, repository reachability, versions, and held packages','package-manager logs'),('kernel signal','kernel messages, module state, device errors, and change timeline','journalctl kernel evidence'),('container failure','image, entrypoint, limits, mounts, health checks, and runtime events','container runtime inspect/logs'),('network path','interface, route, resolver, firewall, MTU, and comparison host','ip, route, and connection evidence'),('process leak','process tree, open handles, restart behavior, and growth over time','process and file-descriptor telemetry'),('file descriptors','process limits, open handles, workload, and service configuration','/proc limits and lsof-style evidence')],
 'DATABASE': [('slow query','plan, duration, waits, reads, statistics, indexes, and deployment timeline','query store or database activity evidence'),('connection exhaustion','pool limits, active sessions, authentication errors, and connection age','session and pool telemetry'),('deadlock','blocking graph, transaction age, lock modes, and application transaction IDs','lock/deadlock diagnostics'),('replication lag','primary/replica state, replay/apply position, network health, and workload','replication status and lag metrics'),('database unavailable','listener, process state, storage, authentication, and recent changes','database logs and service state'),('storage pressure','data/log growth, retention, checkpoints, and capacity thresholds','storage and transaction-log telemetry'),('backup failure','backup job stage, destination access, space, credentials, and recoverability','backup history and repository state'),('authentication','identity mapping, endpoint, policy, certificate, and server-side denial evidence','audit logs and connection diagnostics'),('index regression','plan change, statistics, index state, parameter changes, and last-known-good plan','execution-plan evidence'),('deployment regression','schema/version change, query pattern, plan, and rollback compatibility','release and query telemetry'),('failover','health checks, quorum, role state, client routing, and replication readiness','HA manager and client connection evidence'),('locking','waiters, blockers, transaction scope, isolation, and business impact','lock activity evidence'),('transaction timeout','transaction age, timeout configuration, network path, and application retry','session and application logs'),('data integrity','constraint errors, write path, replication consistency, and affected records','database error and integrity checks'),('maintenance','vacuum/statistics/index maintenance, bloat, workload window, and operational risk','maintenance history and performance evidence')],
 'MIDDLEWARE': [('JVM heap','heap occupancy, allocation rate, GC pauses, workload change, and limits','JVM metrics and GC logs'),('thread pool','active threads, queue depth, request latency, deadlock signals, and downstream state','thread dump and request metrics'),('connection pool','pool limits, active/idle connections, wait time, and database health','pool metrics and dependency checks'),('application timeout','request path, gateway timeout, upstream latency, and downstream evidence','distributed request and access logs'),('Kafka lag','producer rate, consumer rate, partition assignment, broker health, and rebalances','consumer-group and broker metrics'),('broker failure','broker state, disk, network, quorum, client errors, and recent changes','broker logs and cluster state'),('RabbitMQ queue','publish/consume rates, unacked messages, consumer health, and retry behavior','queue and consumer metrics'),('TLS failure','certificate chain, expiry, hostname, trust store, protocol, and clock','handshake and certificate evidence'),('certificate expiry','certificate identity, deployment version, reload behavior, and rollback','certificate inventory and server logs'),('downstream dependency','dependency health, timeout policy, retries, circuit state, and request correlation','application and dependency telemetry'),('server startup','configuration parse, port binding, JVM options, permissions, and dependency order','startup logs and process state'),('GC pause','collector, pause duration, heap pressure, allocation, and traffic pattern','GC logs and JVM metrics'),('API gateway','route, policy, upstream, TLS, timeout, and status-code distribution','gateway access logs'),('queue retry storm','error class, backoff, duplicate risk, poison messages, and consumer state','message headers and retry metrics'),('load balancing','target health, stickiness, routing policy, and per-node latency','load-balancer and application metrics')],
 'CLOUDOPS': [('VM unreachable','instance state, route, security policy, interface, health check, and unaffected peer','cloud network and instance telemetry'),('IAM denial','principal, denied action, resource, policy evaluation, and recent identity change','audit log and policy simulator evidence'),('security group','effective rules, source/destination, port, route, and return path','flow logs and effective policy'),('cloud route','subnet, route table, next hop, peering, and recent changes','route inspection and flow telemetry'),('load balancer','health-check reason, target readiness, listener, policy, and zone distribution','load-balancer target metrics'),('autoscaling','demand, limits, quota, health checks, scaling events, and cooldown','autoscaling activity and capacity data'),('Kubernetes pod','scheduling, image, readiness, resources, node health, and events','Kubernetes events and pod status'),('storage access','identity, endpoint, network policy, encryption, mount, and object state','cloud audit and storage diagnostics'),('cloud DNS','zone, resolver path, record state, TTL, and client location','DNS query and control-plane evidence'),('quota exhaustion','quota dimension, request rate, region, account, and remediation risk','quota and service telemetry'),('regional dependency','zone/region health, dependency topology, failover readiness, and scope','provider health and workload distribution'),('configuration drift','declared state, effective state, change actor, timestamp, and blast radius','config history and resource inspection'),('container capacity','node resources, requests/limits, scheduling, image, and autoscaling','cluster and node metrics'),('object storage failure','bucket policy, identity, endpoint, object key, encryption, and service health','storage audit and request logs'),('cost anomaly','service/resource/time dimensions, usage, tags, and recent changes','billing and resource telemetry')],
 'DEVOPS': [('pipeline failure','failed stage, commit, runner, dependency, credentials scope, and reproducibility','pipeline logs and run metadata'),('deployment regression','artifact, version, configuration, health checks, and last-known-good release','deployment and application evidence'),('build failure','compiler/test output, dependency lock, environment, and changed files','build logs and artifact metadata'),('artifact unavailable','repository, coordinates, credentials, network, retention, and digest','repository logs and artifact manifest'),('container image','image digest, registry, architecture, entrypoint, config, and pull events','runtime and registry evidence'),('Kubernetes rollout','replica state, readiness, events, image, resources, and rollout history','cluster events and rollout status'),('Terraform drift','state, declared config, effective resource, lock, and change ownership','plan output and state metadata'),('secret configuration','secret reference, scope, rotation, mount, and application error','secret audit and deployment evidence'),('rollback failure','known-good artifact, data compatibility, health, approvals, and rollback logs','release history and verification'),('environment mismatch','environment variables, config source, artifact, dependency versions, and target','deployment manifests and runtime config'),('dependency version','lockfile, transitive dependency, build cache, vulnerability, and regression timeline','dependency reports and build evidence'),('certificate deployment','certificate artifact, secret reference, reload, hostname, and expiry','deployment logs and handshake checks'),('test failure','test scope, deterministic reproduction, environment, fixture, and changed code','test results and commit diff'),('release approval','change scope, risk, owner, evidence, rollback, and approval state','change record and release metadata'),('configuration rollback','diff, previous state, state ownership, dependency impact, and verification','version control and runtime comparison')],
 'CYBER': [('suspicious authentication','source, identity, device, time, travel context, MFA, and known administrative activity','identity and authentication logs'),('brute-force indication','failure rate, source distribution, account scope, lockouts, and benign automation','authentication telemetry'),('impossible travel','session evidence, device identity, VPN/proxy, timestamps, and user confirmation','identity provider and endpoint evidence'),('privilege escalation','before/after privilege, actor, approval, process, and affected asset','identity and endpoint audit'),('PowerShell signal','script provenance, signer, parent process, user, command context, and endpoint timeline','PowerShell and endpoint logs'),('endpoint alert','detection rule, process tree, file hash, prevalence, isolation state, and user action','EDR timeline'),('outbound traffic','destination, process, volume, DNS, proxy, asset role, and baseline','network and endpoint telemetry'),('lateral movement','source/target identity, authentication type, service use, timeline, and known admin activity','identity and network evidence'),('IAM misuse','principal, action, resource, source, policy, session context, and change history','cloud audit logs'),('security policy change','actor, rule diff, approval, effective path, traffic impact, and rollback','policy audit and flow evidence'),('certificate anomaly','certificate chain, issuer, hostname, key use, expiry, and endpoint identity','TLS and certificate evidence'),('data access','actor, object, volume, business context, authorization, and exfiltration indicators','data-access audit'),('false positive','rule logic, benign activity, asset role, user confirmation, and correlated signals','alert and activity evidence'),('security outage correlation','event timing, independent outage evidence, causal link, and alternative hypotheses','security and service telemetry'),('evidence integrity','source authenticity, timestamps, collection path, chain of custody, and gaps','forensic metadata and immutable logs')],
}
DIFFICULTIES=['L1_BASIC','L2_INTERMEDIATE','L3_ADVANCED','L4_AMBIGUOUS','L5_CROSS_DOMAIN','L6_CONTRADICTORY_EVIDENCE','L7_INSUFFICIENT_EVIDENCE','L8_HIGH_RISK_PRODUCTION']
CASE_TYPES=['NORMAL']*5+['ABSTENTION','ABSTENTION']+['HARD_NEGATIVE']+['CROSS_DOMAIN','CROSS_DOMAIN']+['REMEDIATION']
OTHER={'WINDOWS':'Network or Database','LINUX':'Network or Middleware','DATABASE':'Linux or Network','MIDDLEWARE':'Database or Network','CLOUDOPS':'Network or DevOps','DEVOPS':'CloudOps or Security','CYBER':'Identity or Network'}

def make_row(domain, family, evidence, tool, i):
    difficulty=DIFFICULTIES[i%len(DIFFICULTIES)]; kind=CASE_TYPES[i%len(CASE_TYPES)]; abstain=kind=='ABSTENTION' or difficulty in ('L6_CONTRADICTORY_EVIDENCE','L7_INSUFFICIENT_EVIDENCE')
    cross=kind=='CROSS_DOMAIN' or difficulty=='L5_CROSS_DOMAIN'; partner=OTHER[domain] if cross else ''
    incident=f'SYN-{domain}-{i+1:03d}'; scenario=f'{family} is reported in a {"shared service" if cross else "domain service"}; evidence is partial and timestamped.'
    user=(f'Investigate {incident}. Observed: {scenario} Initial evidence: {evidence}. '
          f'Provide an evidence-driven investigation. Do not claim a root cause without supporting evidence.')
    answer={"assessment":f"Classify the {family} signal and separate facts from hypotheses.","observedFacts":[evidence],"hypotheses":[{"cause":f"{family} condition","status":"candidate","evidence":[evidence]}],"missingEvidence":[f"Collect {tool} output and compare an unaffected target."],"nextDiagnosticAction":{"action":f"Collect {tool} evidence","reason":"It discriminates between the leading hypotheses."},"toolSelection":{"tool":tool,"reason":"It provides the required domain state."},"rootCause":{"established":False if abstain else True,"cause":"" if abstain else f"{family} condition","evidence":[] if abstain else [evidence]},"remediation":"Use the smallest approved change after evidence confirms the cause.","risk":"Assess scope and require approval before a risky production change.","rollback":"Restore the last known-good state and stop if verification fails.","verification":"Repeat the focused check and confirm the original symptom and dependencies recover.","abstain":abstain,"abstentionReason":"Evidence is insufficient or contradictory; collect the requested evidence before RCA." if abstain else "","escalateTo":[partner] if partner else []}
    system=f'Act as a senior {domain} operations engineer. Use only supplied evidence. Distinguish observed facts, hypotheses, and root cause. Prefer abstention, safe approval, rollback, verification, and evidence-based collaboration.'
    return {"trainingReady":False,"exclusion":"Development draft; requires SME review before training.","messages":[{"role":"system","content":system},{"role":"user","content":user},{"role":"assistant","content":json.dumps(answer,ensure_ascii=False)}],"provenance":{"domain":domain,"incidentId":incident,"incidentFamily":f'{domain}:{family.upper().replace(" ","_")}',"mode":"SIMULATION","source":"SYNTHETIC_BEHAVIOR_DRAFT","reviewerId":"","reviewEventId":""},"metadata":{"difficulty":difficulty,"caseType":kind,"crossDomain":cross,"partnerDomain":partner,"abstention":abstain,"tool":tool,"generationVersion":"domain-behavior-v1"}}

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--output',type=Path,default=OUT); ap.add_argument('--count',type=int,default=150); args=ap.parse_args(); args.output.mkdir(parents=True,exist_ok=True)
    for domain, specs in DOMAINS.items():
        rows=[]
        for i in range(args.count):
            family,evidence,tool=specs[i%len(specs)]; rows.append(make_row(domain,family,evidence,tool,i))
        path=args.output/f'{domain.lower()}-behavior-v1.jsonl'; path.write_text(''.join(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n' for r in rows),encoding='utf-8')
        print(domain,path,len(rows),hashlib.sha256(path.read_bytes()).hexdigest())
if __name__=='__main__': main()
